// mm-ctrl Stripe events. Verifies stripe-signature when a signing secret exists in
// system_config.stripe_webhook_signing_secrets (key 'mmctrl'); processes unverified
// (flagged) until Krish supplies the secret. Consolidates the retired per-product clones.
const SB = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SBH = { apikey: '{{SUPABASE_SERVICE_ROLE_KEY}}', Authorization: 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}', 'Content-Type': 'application/json' };
const item = $input.first();
const hdrs = (item.json && item.json.headers) || {};

// raw body (webhook rawBody option stores it as binary)
let raw = null;
try { const b = item.binary && item.binary.data && item.binary.data.data; if (b) raw = Buffer.from(b, 'base64').toString('utf8'); } catch (e) {}
let evt = null;
try { evt = raw ? JSON.parse(raw) : (item.json.body || null); } catch (e) { evt = item.json.body || null; }
if (!evt) return [{ json: { rejected: true, reason: 'unparseable_body', product: 'mm_ctrl' } }];

// signature verification (arms when secret + crypto available)
let verified = 'no_secret';
function q(params){ const p=[]; for (const k of Object.keys(params)) p.push(encodeURIComponent(k)+'='+encodeURIComponent(params[k])); return p.join('&'); }
try {
  const cfg = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/system_config?' + q({ key: 'eq.stripe_webhook_signing_secrets', select: 'value' }), headers: SBH, json: true });
  const row = Array.isArray(cfg) ? cfg[0] : cfg;
  let secrets = row && row.value;
  if (typeof secrets === 'string') { try { secrets = JSON.parse(secrets); } catch (e) { secrets = null; } }
  const secret = secrets && secrets['mmctrl'];
  if (secret && raw) {
    let crypto = null;
    try { crypto = require('crypto'); } catch (e) {}
    if (!crypto) { verified = 'crypto_unavailable'; }
    else {
      const sig = String(hdrs['stripe-signature'] || '');
      const t = (sig.match(/t=(\d+)/) || [])[1];
      const v1s = [...sig.matchAll(/v1=([a-f0-9]+)/g)].map(m => m[1]);
      if (!t || v1s.length === 0) {
        await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/audit_log', headers: SBH, body: [{ actor: 'system', event_type: 'stripe-signature-invalid', display_message: 'Stripe Revenue Intake (mm-ctrl): missing/malformed stripe-signature header; event REJECTED.', details: JSON.stringify({ product: 'mm_ctrl' }) }], json: true });
        return [{ json: { rejected: true, reason: 'missing_signature', product: 'mm_ctrl' } }];
      }
      const expected = crypto.createHmac('sha256', secret).update(t + '.' + raw, 'utf8').digest('hex');
      if (!v1s.includes(expected)) {
        await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/audit_log', headers: SBH, body: [{ actor: 'system', event_type: 'stripe-signature-invalid', display_message: 'Stripe Revenue Intake (mm-ctrl): signature mismatch; event REJECTED.', details: JSON.stringify({ product: 'mm_ctrl', type: evt.type || null }) }], json: true });
        return [{ json: { rejected: true, reason: 'bad_signature', product: 'mm_ctrl' } }];
      }
      verified = 'verified';
    }
  }
} catch (e) { verified = 'verify_error:' + String(e.message || e).slice(0, 60); }

const t = String(evt.type || '').toLowerCase();
const obj = (evt.data && evt.data.object) || {};
const isPaid = ['checkout.session.completed', 'invoice.payment_succeeded', 'customer.subscription.created', 'customer.subscription.updated'].includes(t);
const isChurned = t === 'customer.subscription.deleted';
const customerId = obj.customer || obj.id || null;
const email = obj.customer_email || (obj.customer_details && obj.customer_details.email) || obj.receipt_email || null;

// Telegram alert (fleet ops chat)
try { await this.helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot{{TELEGRAM_BOT_TOKEN}}/sendMessage', body: { chat_id: '6773796504', text: '💰 mm-ctrl: ' + (evt.type || 'event') + ' - ' + (email || customerId || 'unknown') + (verified === 'verified' ? ' [signed]' : '') }, json: true }); } catch (e) {}

// attribution lookup (same logic the per-product clones used)
let lead = null;
try {
  const found = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/leads?' + q({ select: 'id,promoted_task_id,assignee_agent', email: 'ilike.' + (email || '__none__'), order: 'created_at.desc', limit: '1' }), headers: SBH, json: true });
  if (Array.isArray(found) && found[0]) lead = found[0];
} catch (e) {}
const utm = (obj.metadata && (obj.metadata.utm_source || obj.metadata.attribution_channel)) || null;

// customer upsert (idempotent)
let upserted = false;
if (customerId) {
  const now = new Date().toISOString();
  const price = obj.plan || (obj.items && obj.items.data && obj.items.data[0] && obj.items.data[0].price) || null;
  const mrr = (obj.plan && obj.plan.amount != null) ? obj.plan.amount / 100 : (obj.amount_total != null ? obj.amount_total / 100 : (obj.amount_paid != null ? obj.amount_paid / 100 : null));
  try {
    await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/customers?on_conflict=product,stripe_customer_id', headers: { ...SBH, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: [{
      product: 'mm_ctrl', kind: isChurned ? 'churned' : 'paid', email,
      full_name: (obj.customer_details && obj.customer_details.name) || (obj.metadata && obj.metadata.full_name) || null,
      stripe_customer_id: customerId, stripe_subscription_id: obj.subscription || obj.id || null,
      plan: (price && (price.nickname || price.id)) || (obj.metadata && obj.metadata.plan) || null, mrr_usd: mrr,
      became_paid_at: isPaid && !isChurned ? now : null, churned_at: isChurned ? now : null,
      source: utm, raw: evt,
      attribution_lead_id: lead ? lead.id : null, attribution_task_id: lead ? (lead.promoted_task_id || null) : null,
      attribution_channel: lead ? (utm || ('agent:' + (lead.assignee_agent || 'unknown'))) : (utm || null),
      attribution_confidence: lead ? 'exact_email' : (utm ? 'utm' : 'unattributed'),
    }], json: true });
    upserted = true;
  } catch (e) {}
}

// heartbeat
try { await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/workflow_runs', headers: SBH, body: [{ workflow_id: 'stripe-revenue-intake', workflow_name: 'Stripe | Revenue Intake', agent_id: 'system', status: 'success', outcome: 'mmctrl:' + (evt.type || 'event') + ':' + verified + (upserted ? ':upserted' : ''), outcome_count: upserted ? 1 : 0, cost_estimate_usd: 0.0001, api_calls_count: 5 }], json: true }); } catch (e) {}
return [{ json: { ok: true, product: 'mm_ctrl', type: evt.type || null, verified, upserted } }];

